import type {
  Request,
  Response,
} from "express";

import prisma from "../lib/prisma.js";

import {
  createAgentRun,
  executeAgentRun,
} from "../services/run.service.js";

export const createRun = async (
  req: Request,
  res: Response
) => {
  try {
    const slug = String(
      req.params.slug
    );

    const { run } =
      await createAgentRun(slug);

    void executeAgentRun(
      run.id,
      slug,
      req.body ?? {}
    ).catch((error) => {
      console.error(
        `Background run ${run.id} failed:`,
        error
      );
    });

    return res.status(202).json({
      success: true,

      data: {
        runId: run.id,
        status: run.status,
      },
    });
  } catch (error) {
    if (
      error instanceof Error &&
      error.message ===
        "AGENT_NOT_FOUND"
    ) {
      return res.status(404).json({
        success: false,
        message: "Agent not found",
      });
    }

    if (
      error instanceof Error &&
      error.message ===
        "AGENT_IMPLEMENTATION_NOT_FOUND"
    ) {
      return res.status(500).json({
        success: false,
        message:
          "Agent implementation is unavailable",
      });
    }

    console.error(
      "Failed to create agent run:",
      error
    );

    return res.status(500).json({
      success: false,
      message:
        "Failed to create agent run",
    });
  }
};

export const listRuns = async (
  req: Request,
  res: Response
) => {
  try {
    const requestedLimit = Number(
      req.query.limit ?? 50
    );

    const limit =
      Number.isInteger(requestedLimit) &&
      requestedLimit > 0
        ? Math.min(
            requestedLimit,
            100
          )
        : 50;

    const runs =
      await prisma.run.findMany({
        take: limit,

        orderBy: {
          createdAt: "desc",
        },

        include: {
          agent: {
            select: {
              id: true,
              slug: true,
              name: true,
            },
          },

          _count: {
            select: {
              events: true,
            },
          },
        },
      });

    return res.json({
      success: true,
      data: runs,
    });
  } catch (error) {
    console.error(
      "Failed to list runs:",
      error
    );

    return res.status(500).json({
      success: false,
      message: "Failed to list runs",
    });
  }
};

export const getRun = async (
  req: Request,
  res: Response
) => {
  try {
    const runId = String(
      req.params.runId
    );

    const run =
      await prisma.run.findUnique({
        where: {
          id: runId,
        },

        include: {
          agent: {
            select: {
              id: true,
              slug: true,
              name: true,
            },
          },

          events: {
            orderBy: {
              createdAt: "asc",
            },
          },
        },
      });

    if (!run) {
      return res.status(404).json({
        success: false,
        message: "Run not found",
      });
    }

    return res.json({
      success: true,
      data: run,
    });
  } catch (error) {
    console.error(
      "Failed to fetch run:",
      error
    );

    return res.status(500).json({
      success: false,
      message: "Failed to fetch run",
    });
  }
};